import Foundation

/// `Library/Sounds/probe_alarm.wav`, generated by `WavTone.make()` (S3 §6.4). Notification and AlarmKit sounds are
/// looked up there ([I12], [I19]), so no binary asset is committed.
enum ToneFile {
    static let fileName = "probe_alarm.wav"

    static var url: URL {
        let library = FileManager.default.urls(for: .libraryDirectory, in: .userDomainMask)[0]
        return library.appendingPathComponent("Sounds", isDirectory: true).appendingPathComponent(fileName)
    }

    static var expectedBytes: Int { WavTone.headerSize + TriggerLogic.toneSeconds * 44_100 * 2 }

    /// Writes the tone if it is missing or has the wrong size. Call off the main thread (≈1–2 s in Debug).
    static func ensure() {
        let fm = FileManager.default
        let target = url
        if let size = (try? fm.attributesOfItem(atPath: target.path))?[.size] as? NSNumber, size.intValue == expectedBytes {
            return
        }
        let start = Date()
        var ok = true
        var err: String?
        do {
            try fm.createDirectory(at: target.deletingLastPathComponent(), withIntermediateDirectories: true)
            try WavTone.make(seconds: TriggerLogic.toneSeconds).write(to: target, options: .atomic)
        } catch {
            ok = false
            err = String(describing: error)
        }
        EventLog.shared.log("tone_file", [
            "ok": .flag(ok), "err": .str(err), "bytes": .num(expectedBytes), "ms": .num(Elapsed.ms(since: start)),
        ])
    }
}
